{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Alprazolam, a triazolobenzodiazepine sharing the 5-aryl-7-chloro-1,4-benzodiazepine core, has absolute oral bioavailability 0.92 in humans, indicating minimal first-pass loss.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Estazolam, a close triazolobenzodiazepine analog, has 87% oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Clobazam, a 1,5-benzodiazepine, has 90–100% oral bioavailability in humans, supporting high F across benzodiazepine structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Triazolam, a direct triazolobenzodiazepine analog, has absolute oral bioavailability approximately 45–50% in humans, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Adinazolam, a triazolobenzodiazepine, has absolute oral bioavailability approximately 40%, above the 20% threshold despite moderate first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Zotepine, a tricyclic antipsychotic with a different heterocyclic core, has low oral bioavailability (7–13%), but this is not transferable to the benzodiazepine N-oxide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 7-chloro-5-phenyl-1,4-benzodiazepine N-oxide (chlordiazepoxide-like). Multiple close benzodiazepine analogs have absolute oral bioavailability above 20%, mostly 40–100%, and no transferable evidence indicates F < 20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the exact query molecule (chlordiazepoxide) is present.",
    "The effect of the N-oxide moiety on first-pass extraction is not directly evidenced, though benzodiazepine N-oxides are generally well absorbed.",
    "Some analogs (triazolam, adinazolam) show moderate F, so the quantitative value is uncertain but the threshold decision is robust."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C22", "C13", "C34", "C18", "C05"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "benzodiazepines"
    },
    {
      "applicability": "low",
      "card_ids": ["C37"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "tricyclic antipsychotics"
    }
  ],
  "revision_action": "initial"
}

